namespace vllm {

template <typename scalar_t, typename cache_t, bool IS_NEOX>
inline __device__ void apply_token_rotary_embedding(
    scalar_t* __restrict__ arr, const cache_t* __restrict__ cos_ptr,
    const cache_t* __restrict__ sin_ptr, int rot_offset, int embed_dim,
    const bool inverse) {
  int x_index, y_index;
  float cos_f, sin_f;
  if (IS_NEOX) {
    x_index = rot_offset;
    y_index = embed_dim + rot_offset;
    cos_f = static_cast<float>(VLLM_LDG(cos_ptr + x_index));
    sin_f = static_cast<float>(VLLM_LDG(sin_ptr + x_index));
  } else {
    x_index = 2 * rot_offset;
    y_index = 2 * rot_offset + 1;
    cos_f = static_cast<float>(VLLM_LDG(cos_ptr + x_index / 2));
    sin_f = static_cast<float>(VLLM_LDG(sin_ptr + x_index / 2));
  }
  if (inverse) {
    sin_f = -sin_f;
  }
  const float x_f = static_cast<float>(arr[x_index]);
  const float y_f = static_cast<float>(arr[y_index]);
  arr[x_index] = static_cast<scalar_t>(x_f * cos_f - y_f * sin_f);
  arr[y_index] = static_cast<scalar_t>(y_f * cos_f + x_f * sin_f);
}

template <typename scalar_t, typename cache_t, bool IS_NEOX>
inline __device__ void apply_rotary_embedding(
    scalar_t* __restrict__ query,  // [batch_size, seq_len, num_heads,
                                   // head_size] or [num_tokens, num_heads,
                                   // head_size]
    scalar_t* __restrict__ key,    // nullptr or
                                   // [batch_size, seq_len, num_kv_heads,
                                   // head_size] or [num_tokens, num_kv_heads,
                                   // head_size]
    const cache_t* cache_ptr, const int head_size, const int num_heads,
    const int num_kv_heads, const int rot_dim, const int token_idx,
    const int64_t query_stride, const int64_t key_stride,
    const int64_t head_stride, const int64_t rope_dim_offset,
    const bool inverse) {
  const int embed_dim = rot_dim / 2;
  const cache_t* cos_ptr = cache_ptr;
  const cache_t* sin_ptr = cache_ptr + embed_dim;

  const int nq = num_heads * embed_dim;
  for (int i = threadIdx.x; i < nq; i += blockDim.x) {
    const int head_idx = i / embed_dim;
    const int64_t token_head =
        token_idx * query_stride + head_idx * head_stride + rope_dim_offset;
    const int rot_offset = i % embed_dim;
    apply_token_rotary_embedding<scalar_t, cache_t, IS_NEOX>(
        query + token_head, cos_ptr, sin_ptr, rot_offset, embed_dim, inverse);
  }

  if (key != nullptr) {
    const int nk = num_kv_heads * embed_dim;
    for (int i = threadIdx.x; i < nk; i += blockDim.x) {
      const int head_idx = i / embed_dim;
      const int64_t token_head =
          token_idx * key_stride + head_idx * head_stride + rope_dim_offset;
      const int rot_offset = i % embed_dim;
      apply_token_rotary_embedding<scalar_t, cache_t, IS_NEOX>(
          key + token_head, cos_ptr, sin_ptr, rot_offset, embed_dim, inverse);
    }
  }
}

template <typename scalar_t, typename cache_t, bool IS_NEOX>
__global__ void rotary_embedding_kernel(
    const int64_t* __restrict__ positions,  // [batch_size, seq_len] or
                                            // [num_tokens]
    scalar_t* __restrict__ query,           // [batch_size, seq_len, num_heads,
                                   // head_size] or [num_tokens, num_heads,
                                   // head_size]
    scalar_t* __restrict__ key,  // nullptr or
                                 // [batch_size, seq_len, num_kv_heads,
                                 // head_size] or [num_tokens, num_kv_heads,
                                 // head_size]
    const cache_t* __restrict__ cos_sin_cache,  // [max_position, rot_dim]
    const int rot_dim, const int64_t query_stride, const int64_t key_stride,
    const int64_t head_stride, const int num_heads, const int num_kv_heads,
    const int head_size, const int64_t rope_dim_offset, const bool inverse) {
  const int token_idx = blockIdx.x;
  int64_t pos = positions[token_idx];
  const cache_t* cache_ptr = cos_sin_cache + pos * rot_dim;

  apply_rotary_embedding<scalar_t, cache_t, IS_NEOX>(
      query, key, cache_ptr, head_size, num_heads, num_kv_heads, rot_dim,
      token_idx, query_stride, key_stride, head_stride, rope_dim_offset,
      inverse);
}

// -------------------------------------------------------------------------
// AKO specialized NeoX path.
//
// The generic kernel above is fully dynamic: it divides by a runtime
// ``embed_dim`` per element and touches memory two bytes at a time, which at
// the capture's largest shape (T=16384, 32 q heads + 8 kv heads, head_size
// 128) reaches only ~2.6 TB/s of B200's ~8 TB/s.  This path specializes on
//
//   * full rotary (rot_dim == head_size, no dim offset, not inverse),
//   * NeoX pairing, so lane element i pairs with i + EMBED_DIM,
//   * EMBED_DIM as a template constant, so head/chunk indexing is a shift,
//   * cache dtype == query dtype, so one vector type covers both,
//
// and moves 16 B per access instead of 2 B.
//
// One block per token, one thread per VEC-wide pair group:
// ``blockDim.x == (num_heads + num_kv_heads) * (EMBED_DIM / VEC)`` (320 for
// the captured Llama-3.1-8B shape), so there is no grid-stride loop and no
// bounds test.  Within a warp, lanes cover CPH consecutive chunks of the same
// head, so the cos/sin loads of all lanes fall in one 128 B line and the
// x/y loads of a warp together span a dense 4-head run.
// -------------------------------------------------------------------------
namespace ako {

// A naturally-aligned N-wide vector of T; sized so the load is one LDG.128.
template <typename T, int N>
struct alignas(sizeof(T) * N) Vec {
  T v[N];
};

template <typename scalar_t, int EMBED_DIM, int VEC>
__global__ void rope_neox_vec_kernel(
    const int64_t* __restrict__ positions,
    scalar_t* __restrict__ query,
    scalar_t* __restrict__ key,                 // may be nullptr
    const scalar_t* __restrict__ cos_sin_cache,
    const int64_t query_stride, const int64_t key_stride,
    const int chunks_q) {
  constexpr int CPH = EMBED_DIM / VEC;  // vector chunks per head
  constexpr int ROT = 2 * EMBED_DIM;    // == head_size on this path
  using V = Vec<scalar_t, VEC>;

  const int r = threadIdx.x;
  const int token = blockIdx.x;

  // Resolve the element addresses first: they depend only on the launch
  // coordinates, so these loads issue while the dependent
  // positions -> cos_sin_cache address chain is still in flight.
  int idx = r;
  scalar_t* row;
  if (r < chunks_q) {
    row = query + token * query_stride;
  } else {
    row = key + token * key_stride;
    idx = r - chunks_q;
  }
  const int head = idx / CPH;  // CPH is a power of two constant -> shift
  const int j = (idx - head * CPH) * VEC;
  scalar_t* xp = row + head * ROT + j;
  scalar_t* yp = xp + EMBED_DIM;

  V x = *reinterpret_cast<const V*>(xp);
  V y = *reinterpret_cast<const V*>(yp);

  const scalar_t* crow = cos_sin_cache + positions[token] * ROT;
  const V c = *reinterpret_cast<const V*>(crow + j);
  const V s = *reinterpret_cast<const V*>(crow + EMBED_DIM + j);

#pragma unroll
  for (int i = 0; i < VEC; ++i) {
    // Same fp32 expression shape as apply_token_rotary_embedding, so the
    // results stay bit-identical to the generic kernel.
    const float cos_f = static_cast<float>(c.v[i]);
    const float sin_f = static_cast<float>(s.v[i]);
    const float x_f = static_cast<float>(x.v[i]);
    const float y_f = static_cast<float>(y.v[i]);
    x.v[i] = static_cast<scalar_t>(x_f * cos_f - y_f * sin_f);
    y.v[i] = static_cast<scalar_t>(y_f * cos_f + x_f * sin_f);
  }

  *reinterpret_cast<V*>(xp) = x;
  *reinterpret_cast<V*>(yp) = y;
}

}  // namespace ako

}  // namespace vllm

// ---------------------------------------------------------------------------
// AKO: execution probe. Set FK_ROPE_DEBUG=1 to have every call announce which
// dispatch path it took plus the layout it saw. Read once; off by default so
// the timed path pays nothing.
// ---------------------------------------------------------------------------
#include <cstdio>
#include <cstdlib>

static bool fk_rope_debug() {
  static const bool on = [] {
    const char* e = std::getenv("FK_ROPE_DEBUG");
    return e != nullptr && e[0] != '\0' && e[0] != '0';
  }();
  return on;
}

// Set FK_ROPE_NOFAST=1 to force the generic path (A/B without recompiling).
static bool fk_rope_nofast() {
  static const bool on = [] {
    const char* e = std::getenv("FK_ROPE_NOFAST");
    return e != nullptr && e[0] != '\0' && e[0] != '0';
  }();
  return on;
}

static bool fk_aligned16(const void* p) {
  return (reinterpret_cast<uintptr_t>(p) % 16) == 0;
}

// Try the specialized NeoX path; returns false if any precondition fails, in
// which case the caller falls back to the generic kernel.
//
// NOTE: deliberately *not* predicated on ``is_contiguous()``.  The captured
// query/key are fused-QKV views with stride(0)=6144 over a 4096-wide row, so
// they are never contiguous in the timed calls -- while the correctness rounds
// hand over ``clone()``d (hence contiguous) copies.  An ``is_contiguous()``
// guard therefore validates the fast path and then benchmarks the slow one.
// What the vector loads actually need is: unit last-dim stride, heads packed at
// exactly head_size, a row pitch that keeps every row 16 B aligned, and a
// 16 B aligned base.
template <typename scalar_t, int VEC>
static bool ako_launch_neox(
    const torch::Tensor& positions, torch::Tensor& query,
    std::optional<torch::Tensor>& key, const torch::Tensor& cos_sin_cache,
    int64_t head_size, int num_heads, int num_kv_heads, int rot_dim,
    int64_t query_stride, int64_t key_stride, int64_t head_stride,
    int64_t rope_dim_offset, bool inverse, bool is_neox, int64_t num_tokens,
    cudaStream_t stream) {
  if (fk_rope_nofast()) return false;
  if (!is_neox || inverse || rope_dim_offset != 0) return false;
  if (rot_dim != head_size || head_stride != head_size) return false;
  if (cos_sin_cache.scalar_type() != query.scalar_type()) return false;
  if (query.stride(-1) != 1) return false;
  if (key.has_value() && key->stride(-1) != 1) return false;
  if (!positions.is_contiguous()) return false;

  const int embed_dim = rot_dim / 2;
  if (embed_dim % VEC != 0) return false;
  // Row pitch in elements must keep every row's base 16 B aligned.
  if (query_stride % VEC != 0) return false;
  if (key.has_value() && key_stride % VEC != 0) return false;
  if (!fk_aligned16(query.const_data_ptr())) return false;
  if (key.has_value() && !fk_aligned16(key->const_data_ptr())) return false;
  if (!fk_aligned16(cos_sin_cache.const_data_ptr())) return false;

  const int cph = embed_dim / VEC;
  const int chunks_q = num_heads * cph;
  const int chunks_k = key.has_value() ? num_kv_heads * cph : 0;
  const int chunks_total = chunks_q + chunks_k;
  if (chunks_total == 0 || chunks_total > 1024) return false;

  scalar_t* qp = query.mutable_data_ptr<scalar_t>();
  scalar_t* kp = key.has_value() ? key->mutable_data_ptr<scalar_t>() : nullptr;
  const scalar_t* cp = cos_sin_cache.const_data_ptr<scalar_t>();
  const int64_t* pp = positions.const_data_ptr<int64_t>();

#define AKO_LAUNCH(ED)                                                       \
  vllm::ako::rope_neox_vec_kernel<scalar_t, (ED), VEC>                       \
      <<<dim3(num_tokens), dim3(chunks_total), 0, stream>>>(                 \
          pp, qp, kp, cp, query_stride, key_stride, chunks_q);               \
  break;

  switch (embed_dim) {
    case 64: AKO_LAUNCH(64)     // head_size 128: Llama / Qwen / most models
    case 32: AKO_LAUNCH(32)     // head_size 64
    case 48: AKO_LAUNCH(48)     // head_size 96
    case 80: AKO_LAUNCH(80)     // head_size 160
    case 96: AKO_LAUNCH(96)     // head_size 192
    case 128: AKO_LAUNCH(128)   // head_size 256
    default: return false;
  }
#undef AKO_LAUNCH

  if (fk_rope_debug()) {
    fprintf(stderr,
            "[fk-rope-ako] FAST   T=%ld nh=%d nkv=%d hs=%ld embed=%d vec=%d "
            "block=%d qs=%ld ks=%ld qcontig=%d\n",
            (long)num_tokens, num_heads, num_kv_heads, (long)head_size,
            embed_dim, VEC, chunks_total, (long)query_stride, (long)key_stride,
            (int)query.is_contiguous());
  }
  return true;
}

void rotary_embedding(
    torch::Tensor& positions,  // [batch_size, seq_len] or [num_tokens]
    torch::Tensor&
        query,  // [batch_size, seq_len, num_heads * head_size] or
                // [num_tokens, num_heads * head_size] or
                // [batch_size, seq_len, num_heads, head_size] or
                // [num_tokens, num_heads, head_size]
    std::optional<torch::Tensor> key,
    // null or
    // [batch_size, seq_len, num_kv_heads * head_size] or
    // [num_tokens, num_kv_heads * head_size] or
    // [batch_size, seq_len, num_heads, head_size] or
    // [num_tokens, num_heads, head_size]
    int64_t head_size,
    torch::Tensor& cos_sin_cache,  // [max_position, rot_dim]
    bool is_neox, int64_t rope_dim_offset, bool inverse) {
  // num_tokens = batch_size * seq_len
  int64_t num_tokens = positions.numel();
  int positions_ndim = positions.dim();

  // Make sure num_tokens dim is consistent across positions, query, and key
  STD_TORCH_CHECK(
      positions_ndim == 1 || positions_ndim == 2,
      "positions must have shape [num_tokens] or [batch_size, seq_len]");
  if (positions_ndim == 1) {
    STD_TORCH_CHECK(
        query.size(0) == positions.size(0) &&
            (!key.has_value() || key->size(0) == positions.size(0)),
        "query, key and positions must have the same number of tokens");
  }
  if (positions_ndim == 2) {
    STD_TORCH_CHECK(
        query.size(0) == positions.size(0) &&
            (!key.has_value() || key->size(0) == positions.size(0)) &&
            query.size(1) == positions.size(1) &&
            (!key.has_value() || key->size(1) == positions.size(1)),
        "query, key and positions must have the same batch_size and seq_len");
  }

  // Make sure head_size is valid for query and key
  // hidden_size = num_heads * head_size
  int query_hidden_size = query.numel() / num_tokens;
  int key_hidden_size = key.has_value() ? key->numel() / num_tokens : 0;
  STD_TORCH_CHECK(query_hidden_size % head_size == 0);
  STD_TORCH_CHECK(key_hidden_size % head_size == 0);

  // Make sure query and key have consistent number of heads
  int num_heads = query_hidden_size / head_size;
  int num_kv_heads = key.has_value() ? key_hidden_size / head_size : num_heads;
  STD_TORCH_CHECK(num_heads % num_kv_heads == 0);

  int rot_dim = cos_sin_cache.size(1);
  int seq_dim_idx = positions_ndim - 1;
  int64_t query_stride = query.stride(seq_dim_idx);
  int64_t key_stride = key.has_value() ? key->stride(seq_dim_idx) : 0;

  STD_TORCH_CHECK((rot_dim + rope_dim_offset) <= head_size);
  // Determine head stride: for [*, heads, head_size] use stride of last dim;
  // for flat [*, heads*head_size], heads blocks are contiguous of size
  // head_size
  int query_ndim = query.dim();
  int64_t head_stride =
      (query_ndim == positions_ndim + 2) ? query.stride(-2) : head_size;

  dim3 grid(num_tokens);
  dim3 block(std::min<int64_t>(num_heads * rot_dim / 2, 512));
  const c10::cuda::CUDAGuard device_guard(query.get_device());
  const cudaStream_t stream = get_current_cuda_stream();

  // Specialized NeoX path first; it declines and we fall through otherwise.
  if (num_tokens > 0) {
    bool took_fast = false;
    switch (query.scalar_type()) {
      case at::ScalarType::BFloat16:
        took_fast = ako_launch_neox<at::BFloat16, 8>(
            positions, query, key, cos_sin_cache, head_size, num_heads,
            num_kv_heads, rot_dim, query_stride, key_stride, head_stride,
            rope_dim_offset, inverse, is_neox, num_tokens, stream);
        break;
      case at::ScalarType::Half:
        took_fast = ako_launch_neox<at::Half, 8>(
            positions, query, key, cos_sin_cache, head_size, num_heads,
            num_kv_heads, rot_dim, query_stride, key_stride, head_stride,
            rope_dim_offset, inverse, is_neox, num_tokens, stream);
        break;
      case at::ScalarType::Float:
        took_fast = ako_launch_neox<float, 4>(
            positions, query, key, cos_sin_cache, head_size, num_heads,
            num_kv_heads, rot_dim, query_stride, key_stride, head_stride,
            rope_dim_offset, inverse, is_neox, num_tokens, stream);
        break;
      default:
        break;
    }
    if (took_fast) {
      STD_CUDA_KERNEL_LAUNCH_CHECK();
      return;
    }
  }

  if (fk_rope_debug()) {
    fprintf(stderr,
            "[fk-rope-ako] GENERIC T=%ld nh=%d nkv=%d hs=%ld rot=%d "
            "qs=%ld ks=%ld hstride=%ld neox=%d qdt=%d cdt=%d "
            "qcontig=%d qalign=%d\n",
            (long)num_tokens, num_heads, num_kv_heads, (long)head_size, rot_dim,
            (long)query_stride, (long)key_stride, (long)head_stride,
            (int)is_neox, (int)query.scalar_type(),
            (int)cos_sin_cache.scalar_type(), (int)query.is_contiguous(),
            (int)(((uintptr_t)query.const_data_ptr() % 16) == 0));
  }
  VLLM_STABLE_DISPATCH_FLOATING_TYPES(
      query.scalar_type(), "rotary_embedding", [&] {
        using query_t = scalar_t;
        VLLM_STABLE_DISPATCH_FLOATING_TYPES(
            cos_sin_cache.scalar_type(), "rotary_embedding_cache", [&] {
              using cache_t = scalar_t;
              if (is_neox) {
                vllm::rotary_embedding_kernel<query_t, cache_t, true>
                    <<<grid, block, 0, stream>>>(
                        positions.const_data_ptr<int64_t>(),
                        query.mutable_data_ptr<query_t>(),
                        key.has_value() ? key->mutable_data_ptr<query_t>()
                                        : nullptr,
                        cos_sin_cache.const_data_ptr<cache_t>(), rot_dim,
                        query_stride, key_stride, head_stride, num_heads,
                        num_kv_heads, head_size, rope_dim_offset, inverse);
              } else {
                vllm::rotary_embedding_kernel<query_t, cache_t, false>
                    <<<grid, block, 0, stream>>>(
                        positions.const_data_ptr<int64_t>(),
                        query.mutable_data_ptr<query_t>(),
                        key.has_value() ? key->mutable_data_ptr<query_t>()
                                        : nullptr,
                        cos_sin_cache.const_data_ptr<cache_t>(), rot_dim,
                        query_stride, key_stride, head_stride, num_heads,
                        num_kv_heads, head_size, rope_dim_offset, inverse);
              }
            });
      });
}

// ===== pybind module (per-op) =====
#include <torch/extension.h>
static void rotary_embedding_py(
    torch::Tensor& positions, torch::Tensor& query,
    std::optional<torch::Tensor> key, int64_t head_size,
    torch::Tensor& cos_sin_cache, bool is_neox,
    int64_t rope_dim_offset = 0, bool inverse = false) {
  rotary_embedding(positions, query, key, head_size, cos_sin_cache, is_neox,
                   rope_dim_offset, inverse);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("rotary_embedding", &rotary_embedding_py, "vLLM rotary_embedding (CUDA)",
        py::arg("positions"), py::arg("query"), py::arg("key"),
        py::arg("head_size"), py::arg("cos_sin_cache"), py::arg("is_neox"),
        py::arg("rope_dim_offset") = 0, py::arg("inverse") = false);
}

